function NeuralNet({ T, s, x, y, w, h }) {
  const layers = [4, 6, 6, 3];
  const nodes = layers.map((n, li) => Array.from({ length: n }, (_, k) => [40 + (li / (layers.length - 1)) * (w - 80), ((k + 1) / (n + 1)) * h]));
  const edges = [];
  for (let li = 0; li < layers.length - 1; li++) nodes[li].forEach((a, i) => nodes[li + 1].forEach((b, j) => edges.push([a, b, li, i * 7 + j * 3 + li * 11])));
  const draw = MOTION.draw(s + .3, s + 1.8)(T);
  const live = T > s + 1.6;
  return (
    <svg width={w} height={h} style={{ position: 'absolute', left: x, top: y, overflow: 'visible' }}>
      {edges.map(([a, b, li], k) => { const p = cl(draw * 3 - li); return <line key={k} x1={a[0]} y1={a[1]} x2={a[0] + (b[0] - a[0]) * p} y2={a[1] + (b[1] - a[1]) * p} stroke="rgba(244,241,234,.16)" strokeWidth="1.5" />; })}
      {live ? edges.filter((_, k) => k % 3 === 0).map(([a, b, li, seed], k) => {
        const p = (((T - s) * .7 + (seed % 13) / 13) % 1 + 1) % 1;
        return <circle key={'p' + k} cx={a[0] + (b[0] - a[0]) * p} cy={a[1] + (b[1] - a[1]) * p} r="5" fill={OR} opacity={Math.sin(Math.PI * p) * .9} />;
      }) : null}
      {nodes.map((col, li) => col.map((n, k) => {
        const sc = MOTION.pop(s + .2 + li * .35 + k * .04, s + .6 + li * .35 + k * .04)(T);
        const out = li === layers.length - 1;
        return <rect key={li + '-' + k} x={n[0] - 14} y={n[1] - 14} width="28" height="28" fill={out ? OR : BK} stroke={out ? OR : IV} strokeWidth="2.5" transform={`translate(${n[0]} ${n[1]}) scale(${sc}) translate(${-n[0]} ${-n[1]})`} />;
      }))}
    </svg>
  );
}

