const CAPS = { Hook: 'Payments, grocery, rides, learning, healthcare. We build the software behind them.', Brand: 'Mariox Software. AI and product engineering since 2016.', Culture: 'Client workshops, training sessions and a team that stays.', Offices: 'Four offices across three time zones.', Promise: 'Strategy, design, engineering and AI. One senior team.', Industries: 'Ride-hailing, grocery, food, fintech, healthcare and more.', Leadership: 'Led by founders who still work on the builds.', AIIntro: 'We build AI that works inside real products, on real data.', AIServices: 'Agents, generative AI, vision, NLP, ML and MLOps.', Clients: 'Trusted by brands in four countries.', Team: '100+ engineers, all in-house.', Close: 'Let’s build what’s next.' };

function Captions({ T, CUES }) {
  const sc = sceneAt(T, CUES), keys = Object.keys(CUES), i = keys.indexOf(sc);
  const a = CUES[sc], b = i < keys.length - 1 ? CUES[keys[i + 1]] : a + 6;
  const op = cl((T - a - .3) / .3) * cl((b - .3 - T) / .3);
  return (
    <div style={{ position: 'absolute', left: 0, right: 0, bottom: 34, display: 'flex', justifyContent: 'center', zIndex: 30, opacity: op }}>
      <div style={{ background: 'rgba(8,7,10,.82)', color: IV, fontFamily: SANS, fontSize: 34, letterSpacing: '-.01em', padding: '12px 26px' }}>{CAPS[sc]}</div>
    </div>
  );
}

function Film() {
  const { T, CUES } = useComposition();
  const [t] = window.useTweaks(window.TWEAK_DEFAULTS || {});
  return (
    <div data-screen-label={`t=${Math.floor(T)}s`} style={{ position: 'absolute', inset: 0, background: BK, overflow: 'hidden', fontFamily: SANS }}>
      <Hook T={T} CUES={CUES} />
      <Culture T={T} CUES={CUES} />
      <Offices T={T} CUES={CUES} />
      <PromiseScene T={T} CUES={CUES} />
      <AIIntro T={T} CUES={CUES} />
      <AIServices T={T} CUES={CUES} />
      <Industries T={T} CUES={CUES} />
      <Clients T={T} CUES={CUES} />
      <Leadership T={T} CUES={CUES} />
      <Team T={T} CUES={CUES} />
      <Close T={T} CUES={CUES} />
      <Chrome T={T} CUES={CUES} />
      {t.captions ? <Captions T={T} CUES={CUES} /> : null}
    </div>
  );
}

function FilmTweaks() {
  const [t, setTweak] = window.useTweaks(window.TWEAK_DEFAULTS || {});
  const { TweaksPanel, TweakSection, TweakToggle } = window;
  return (
    <TweaksPanel>
      <TweakSection label="Playback" />
      <TweakToggle label="Motion editor" value={t.motionEditor} onChange={(v) => setTweak('motionEditor', v)} />
      <TweakSection label="Accessibility" />
      <TweakToggle label="Captions" value={t.captions} onChange={(v) => setTweak('captions', v)} />
    </TweaksPanel>
  );
}

function MarioxFilm65() {
  return (
    <>
      <CompositionStage width={W} height={H} scenes={window.OM_SCENES} playback={window.OM_PLAYBACK} bg={BK}>
        <Film />
      </CompositionStage>
      <FilmTweaks />
    </>
  );
}

window.MarioxFilm65 = MarioxFilm65;
